-- TORVO V2 SECURE SALES TEAM RPCS
-- Owner/Admin manage areas, dealer ownership and targets. Salesmen receive only their active mapped dealers.
create or replace function assign_salesman_area(p_salesman uuid,p_state text,p_district text default null,p_city text default null) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;s app_users%rowtype;rid uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Owner/Admin required';end if;select * into s from app_users where id=p_salesman and active=true and role='salesman';if not found then raise exception 'Active salesman required';end if;if nullif(trim(p_state),'') is null then raise exception 'State required';end if;if nullif(trim(p_city),'') is not null and nullif(trim(p_district),'') is null then raise exception 'District required for city mapping';end if;if exists(select 1 from salesman_area_mappings where salesman_id=p_salesman and active=true and upper(state)=upper(trim(p_state)) and coalesce(upper(district),'')=coalesce(upper(nullif(trim(p_district),'')),'') and coalesce(upper(city),'')=coalesce(upper(nullif(trim(p_city),'')),'')) then raise exception 'Area already mapped';end if;insert into salesman_area_mappings(salesman_id,state,district,city,assigned_by)values(p_salesman,upper(trim(p_state)),upper(nullif(trim(p_district),'')),upper(nullif(trim(p_city),'')),a.id)returning id into rid;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'SALESMAN_AREA_ASSIGNED','salesman_area_mapping',rid::text,jsonb_build_object('salesman',p_salesman,'state',upper(trim(p_state)),'district',upper(nullif(trim(p_district),'')),'city',upper(nullif(trim(p_city),''))));return rid;end;$$;
create or replace function end_salesman_area(p_mapping uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Owner/Admin required';end if;if nullif(trim(p_reason),'') is null then raise exception 'Reason required';end if;update salesman_area_mappings set active=false,ended_at=now() where id=p_mapping and active=true;if not found then raise exception 'Active mapping not found';end if;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'SALESMAN_AREA_ENDED','salesman_area_mapping',p_mapping::text,jsonb_build_object('reason',trim(p_reason)));end;$$;
create or replace function assign_dealer_to_salesman(p_salesman uuid,p_dealer uuid,p_reason text default null) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;s app_users%rowtype;old salesman_dealer_mappings%rowtype;rid uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Owner/Admin required';end if;select * into s from app_users where id=p_salesman and active=true and role='salesman';if not found then raise exception 'Active salesman required';end if;if not exists(select 1 from dealers where id=p_dealer) then raise exception 'Dealer not found';end if;select * into old from salesman_dealer_mappings where dealer_id=p_dealer and active=true for update;if found and old.salesman_id=p_salesman then raise exception 'Dealer already assigned to this salesman';end if;if found then if nullif(trim(p_reason),'') is null then raise exception 'Transfer reason required';end if;update salesman_dealer_mappings set active=false,ended_at=now(),transfer_reason=trim(p_reason) where id=old.id;end if;insert into salesman_dealer_mappings(salesman_id,dealer_id,assigned_by,transfer_reason)values(p_salesman,p_dealer,a.id,case when found then trim(p_reason) else null end)returning id into rid;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,case when old.id is null then 'DEALER_ASSIGNED_TO_SALESMAN' else 'DEALER_TRANSFERRED_TO_SALESMAN' end,'salesman_dealer_mapping',rid::text,jsonb_build_object('dealer',p_dealer,'salesman',p_salesman,'previous_salesman',old.salesman_id,'reason',p_reason));return rid;end;$$;
create or replace function set_salesman_target(p_salesman uuid,p_period_type text,p_start date,p_end date,p_sales numeric,p_billed integer,p_new integer) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;rid uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Owner/Admin required';end if;if not exists(select 1 from app_users where id=p_salesman and active=true and role='salesman') then raise exception 'Active salesman required';end if;if p_period_type not in('monthly','quarterly','financial_year') or p_end<p_start or least(p_sales,p_billed,p_new)<0 then raise exception 'Invalid target';end if;insert into salesman_targets(salesman_id,period_type,period_start,period_end,sales_value_target,billed_dealer_target,new_dealer_target,assigned_by)values(p_salesman,p_period_type,p_start,p_end,p_sales,p_billed,p_new,a.id)on conflict(salesman_id,period_type,period_start,period_end)do update set sales_value_target=excluded.sales_value_target,billed_dealer_target=excluded.billed_dealer_target,new_dealer_target=excluded.new_dealer_target,assigned_by=a.id,created_at=now() returning id into rid;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'SALESMAN_TARGET_SET','salesman_target',rid::text,jsonb_build_object('salesman',p_salesman,'period',p_period_type,'start',p_start,'end',p_end,'sales',p_sales,'billed_dealers',p_billed,'new_dealers',p_new));return rid;end;$$;
create or replace function my_salesman_dealers() returns table(dealer_id uuid,dealer_code text,shop_name text,contact_person text,mobile text,whatsapp text,state text,district text,city text,status text,rate_group text) language plpgsql security definer set search_path=public as $$declare s uuid;begin select id into s from app_users where auth_user_id=auth.uid() and active=true and role='salesman';if s is null then raise exception 'Salesman login required';end if;return query select d.id,d.dealer_code,d.shop_name,d.contact_person,d.mobile,d.whatsapp,d.state,d.district,d.city,d.status,d.rate_group from salesman_dealer_mappings m join dealers d on d.id=m.dealer_id where m.salesman_id=s and m.active=true order by d.shop_name;end;$$;
create or replace function my_salesman_areas() returns table(mapping_id uuid,state text,district text,city text,assigned_at timestamptz) language plpgsql security definer set search_path=public as $$declare s uuid;begin select id into s from app_users where auth_user_id=auth.uid() and active=true and role='salesman';if s is null then raise exception 'Salesman login required';end if;return query select m.id,m.state,m.district,m.city,m.assigned_at from salesman_area_mappings m where m.salesman_id=s and m.active=true order by m.state,m.district,m.city;end;$$;
create or replace function my_salesman_targets() returns table(id uuid,period_type text,period_start date,period_end date,sales_value_target numeric,billed_dealer_target integer,new_dealer_target integer) language plpgsql security definer set search_path=public as $$declare s uuid;begin select app_users.id into s from app_users where auth_user_id=auth.uid() and active=true and role='salesman';if s is null then raise exception 'Salesman login required';end if;return query select t.id,t.period_type,t.period_start,t.period_end,t.sales_value_target,t.billed_dealer_target,t.new_dealer_target from salesman_targets t where t.salesman_id=s and t.period_end>=current_date order by t.period_start;end;$$;
-- Progress is derived from delivered sales and approved dealers assigned to this salesman; no demo numbers.
create or replace function my_salesman_target_progress() returns table(target_id uuid,period_type text,period_start date,period_end date,sales_target numeric,sales_achieved numeric,billed_target integer,billed_achieved bigint,new_target integer,new_achieved bigint) language plpgsql security definer set search_path=public as $$declare s uuid;begin select id into s from app_users where auth_user_id=auth.uid() and active=true and role='salesman';if s is null then raise exception 'Salesman login required';end if;return query select t.id,t.period_type,t.period_start,t.period_end,t.sales_value_target,coalesce((select sum(sd.final_payable) from sales_documents sd join dispatches dp on dp.estimate_id=sd.id where sd.doc_type='estimate' and dp.status='delivered' and sd.dealer_id in(select dealer_id from salesman_dealer_mappings where salesman_id=s and active=true) and coalesce(dp.delivered_at,sd.created_at)::date between t.period_start and t.period_end),0),t.billed_dealer_target,coalesce((select count(distinct sd.dealer_id) from sales_documents sd join dispatches dp on dp.estimate_id=sd.id where sd.doc_type='estimate' and dp.status='delivered' and sd.dealer_id in(select dealer_id from salesman_dealer_mappings where salesman_id=s and active=true) and coalesce(dp.delivered_at,sd.created_at)::date between t.period_start and t.period_end),0),t.new_dealer_target,coalesce((select count(*) from dealers d join salesman_dealer_mappings m on m.dealer_id=d.id where m.salesman_id=s and m.active=true and d.status='approved' and d.approved_at::date between t.period_start and t.period_end),0) from salesman_targets t where t.salesman_id=s and t.period_end>=current_date order by t.period_start;end;$$;
-- Salesman assisted order: only mapped dealer, server-side rates, explicit dealer consent evidence and immutable audit trail.
create or replace function salesman_submit_dealer_order(p_dealer uuid,p_lines jsonb,p_consent_method text,p_consent_note text default null) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;rg text;oid uuid;ln jsonb;iid uuid;q numeric;r numeric;sub numeric:=0;begin select * into a from app_users where auth_user_id=auth.uid() and active=true and role='salesman';if not found then raise exception 'Salesman login required';end if;if not salesman_can_access_dealer(a.id,p_dealer) then raise exception 'Dealer is not assigned to this salesman';end if;if p_consent_method not in('whatsapp_confirmation','phone','written_slip','in_person') then raise exception 'Valid dealer consent method required';end if;if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Order lines required';end if;select rate_group into rg from dealers where id=p_dealer and status='approved' for update;if rg is null then raise exception 'Approved dealer with rate group required';end if;insert into sales_documents(dealer_id,doc_type,status,subtotal,final_payable,created_by,revision_no,dealer_modification_limit,dealer_modifications_used,order_source,assisted_by,dealer_consent_method,dealer_consent_note) values(p_dealer,'sales_order','submitted',0,0,a.id,1,2,0,'salesman_assisted',a.id,p_consent_method,nullif(trim(p_consent_note),'')) returning id into oid;for ln in select * from jsonb_array_elements(p_lines) loop begin iid:=(ln->>'item_id')::uuid;q:=(ln->>'qty')::numeric;exception when others then raise exception 'Invalid order line';end;if q is null or q<=0 then raise exception 'Invalid quantity';end if;perform 1 from catalog_items where id=iid and active=true;if not found then raise exception 'Item unavailable';end if;select selling_rate into r from item_rates where item_id=iid and rate_group=rg and min_qty<=q order by min_qty desc limit 1;if r is null then raise exception 'Rate unavailable for an item';end if;insert into sales_document_lines(document_id,item_id,qty,rate,amount) values(oid,iid,q,r,round(q*r,2));sub:=sub+round(q*r,2);end loop;update sales_documents set subtotal=sub,final_payable=sub,root_order_id=oid where id=oid;insert into sales_order_revisions(sales_order_id,revision_no,changed_by,actor_role,change_reason,after_data) values(oid,1,a.id,'salesman','SALESMAN ASSISTED PURCHASE ORDER',jsonb_build_object('dealer',p_dealer,'subtotal',sub,'consent_method',p_consent_method,'lines',p_lines));insert into dealer_consent_events(dealer_id,salesman_id,entity_type,entity_id,method,verified,verification_reference,verified_at) values(p_dealer,a.id,'purchase_order',oid,case p_consent_method when 'whatsapp_confirmation' then 'whatsapp_confirmation' when 'phone' then 'phone' when 'written_slip' then 'written_slip' else 'in_person' end,true,nullif(trim(p_consent_note),''),now());insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'SALESMAN_ASSISTED_ORDER_SUBMITTED','sales_order',oid::text,jsonb_build_object('dealer',p_dealer,'subtotal',sub,'consent_method',p_consent_method));return oid;end;$$;
revoke all on function assign_salesman_area(uuid,text,text,text),end_salesman_area(uuid,text),assign_dealer_to_salesman(uuid,uuid,text),set_salesman_target(uuid,text,date,date,numeric,integer,integer),my_salesman_dealers(),my_salesman_areas(),my_salesman_targets(),my_salesman_target_progress(),salesman_submit_dealer_order(uuid,jsonb,text,text) from public,anon;
grant execute on function assign_salesman_area(uuid,text,text,text),end_salesman_area(uuid,text),assign_dealer_to_salesman(uuid,uuid,text),set_salesman_target(uuid,text,date,date,numeric,integer,integer),my_salesman_dealers(),my_salesman_areas(),my_salesman_targets(),my_salesman_target_progress(),salesman_submit_dealer_order(uuid,jsonb,text,text) to authenticated;
